/**
 * طابور مزامنة قسم «يومية المكنة» عند إلغاء تأجيل المزامنة.
 */
import { db } from '@/firebase';
import {
  addDoc,
  collection,
  deleteDoc,
  doc,
  getDocs,
  serverTimestamp,
  setDoc,
} from 'firebase/firestore';
import { isManualFirestoreHoldEffective } from '@/utils/manualFirestoreSyncHold';

export type MachineDailyQueuedOp =
  | { t: 'setMachine'; shopId: string; mid: string; patch: Record<string, unknown> }
  | { t: 'machineCreate'; shopId: string; mid: string; name: string }
  | { t: 'addDelivery'; shopId: string; mid: string; did?: string; data: Record<string, unknown> }
  | { t: 'addTransfer'; shopId: string; mid: string; tid?: string; data: Record<string, unknown> }
  | { t: 'addWithdrawal'; shopId: string; mid: string; wid?: string; data: Record<string, unknown> }
  | { t: 'deleteTransfer'; shopId: string; mid: string; tid: string }
  | { t: 'deleteAllTransfers'; shopId: string; mid: string }
  | { t: 'deleteAllDeliveries'; shopId: string; mid: string }
  | { t: 'deleteWithdrawal'; shopId: string; mid: string; wid: string }
  | { t: 'deleteMachine'; shopId: string; mid: string };

export const machineDailyQueueKey = (uid: string) => `machineDaily_syncQueue_${uid}`;

export function readMachineDailyQueue(uid: string): MachineDailyQueuedOp[] {
  try {
    const raw = localStorage.getItem(machineDailyQueueKey(uid));
    if (!raw) return [];
    const a = JSON.parse(raw);
    return Array.isArray(a) ? a : [];
  } catch {
    return [];
  }
}

export function appendMachineDailyQueue(uid: string, op: MachineDailyQueuedOp) {
  try {
    const cur = readMachineDailyQueue(uid);
    cur.push(op);
    localStorage.setItem(machineDailyQueueKey(uid), JSON.stringify(cur));
  } catch {
    /* ignore */
  }
}

async function deleteMachineSubcollections(shopId: string, mid: string) {
  const base = collection(db, 'shops', shopId, 'machines', mid, 'transfers');
  const base2 = collection(db, 'shops', shopId, 'machines', mid, 'deliveries');
  const base3 = collection(db, 'shops', shopId, 'machines', mid, 'withdrawals');
  for (const col of [base, base2, base3]) {
    try {
      const snap = await getDocs(col);
      await Promise.all(snap.docs.map((d) => deleteDoc(d.ref)));
    } catch {
      /* ignore */
    }
  }
}

export async function flushMachineDailyQueue(uid: string): Promise<{ ok: number; failed: number }> {
  if (!uid || isManualFirestoreHoldEffective(uid)) return { ok: 0, failed: 0 };
  let ops: MachineDailyQueuedOp[];
  try {
    const raw = localStorage.getItem(machineDailyQueueKey(uid));
    if (!raw) return { ok: 0, failed: 0 };
    ops = JSON.parse(raw);
    if (!Array.isArray(ops) || ops.length === 0) return { ok: 0, failed: 0 };
    localStorage.setItem(machineDailyQueueKey(uid), '[]');
  } catch {
    return { ok: 0, failed: 0 };
  }

  const failed: MachineDailyQueuedOp[] = [];
  let ok = 0;

  for (const op of ops) {
    try {
      switch (op.t) {
        case 'setMachine': {
          await setDoc(
            doc(db, 'shops', op.shopId, 'machines', op.mid),
            { ...op.patch, updatedAt: serverTimestamp() },
            { merge: true }
          );
          break;
        }
        case 'machineCreate': {
          await setDoc(doc(db, 'shops', op.shopId, 'machines', op.mid), {
            name: op.name,
            shopId: op.shopId,
            createdAt: serverTimestamp(),
            updatedAt: serverTimestamp(),
            isActive: true,
          });
          break;
        }
        case 'addDelivery': {
          const delCol = collection(db, 'shops', op.shopId, 'machines', op.mid, 'deliveries');
          const payload = { ...op.data, createdAt: serverTimestamp() };
          if (op.did) {
            await setDoc(doc(delCol, op.did), payload);
          } else {
            await addDoc(delCol, payload);
          }
          await setDoc(
            doc(db, 'shops', op.shopId, 'machines', op.mid),
            { lastDeliveryAt: serverTimestamp(), updatedAt: serverTimestamp() },
            { merge: true }
          );
          break;
        }
        case 'addTransfer': {
          const trCol = collection(db, 'shops', op.shopId, 'machines', op.mid, 'transfers');
          const payload = { ...op.data, createdAt: serverTimestamp() };
          if (op.tid) {
            await setDoc(doc(trCol, op.tid), payload);
          } else {
            await addDoc(trCol, payload);
          }
          break;
        }
        case 'addWithdrawal': {
          const wCol = collection(db, 'shops', op.shopId, 'machines', op.mid, 'withdrawals');
          const payload = { ...op.data, createdAt: serverTimestamp() };
          if (op.wid) {
            await setDoc(doc(wCol, op.wid), payload);
          } else {
            await addDoc(wCol, payload);
          }
          break;
        }
        case 'deleteTransfer': {
          await deleteDoc(doc(db, 'shops', op.shopId, 'machines', op.mid, 'transfers', op.tid));
          break;
        }
        case 'deleteAllTransfers': {
          const snap = await getDocs(collection(db, 'shops', op.shopId, 'machines', op.mid, 'transfers'));
          await Promise.all(snap.docs.map((d) => deleteDoc(d.ref)));
          break;
        }
        case 'deleteAllDeliveries': {
          const snap = await getDocs(collection(db, 'shops', op.shopId, 'machines', op.mid, 'deliveries'));
          await Promise.all(snap.docs.map((d) => deleteDoc(d.ref)));
          break;
        }
        case 'deleteWithdrawal': {
          await deleteDoc(doc(db, 'shops', op.shopId, 'machines', op.mid, 'withdrawals', op.wid));
          break;
        }
        case 'deleteMachine': {
          await deleteMachineSubcollections(op.shopId, op.mid);
          await deleteDoc(doc(db, 'shops', op.shopId, 'machines', op.mid));
          break;
        }
        default:
          break;
      }
      ok += 1;
    } catch {
      failed.push(op);
    }
  }

  if (failed.length > 0) {
    try {
      const rest = readMachineDailyQueue(uid);
      localStorage.setItem(machineDailyQueueKey(uid), JSON.stringify([...failed, ...rest]));
    } catch {
      /* ignore */
    }
  }

  return { ok, failed: failed.length };
}
